validation_rules {
 "note": "Checks over a ledger. V02-V06 define integrity breaks and the verified prefix; the others reject an event as illegal (retained, unverified, contributes nothing) or flag a derived-value mismatch. All checks are data predicates, none grants authority.",
 "V01": "ledger_id equals the receipt ledger_id and receipt_sha256 equals the hash of the cited receipt bytes; an unverified or null receipt means no dispatch event is legal",
 "V02": "seq contiguous from 1 with no gap or duplicate",
 "V03": "prev_event_sha256 equals the previous event_sha256 (null only at seq 1)",
 "V04": "event_sha256 equals the recomputed canonical hash",
 "V05": "event_utc not earlier than the previous event in the main segment",
 "V06": "persistence is acknowledged",
 "V07": "dispatch_recorded and reservation_made name the next slot in the frozen order",
 "V08": "no slot is open (reserved, dispatched or delivered but not closed) when a reservation or dispatch begins",
 "V09": "dispatch_recorded is preceded by reservation_made for the same slot with all gate fields true",
 "V10": "attempt_id is unique per dispatched or unsolicited attempt and attempt_order is strictly increasing across the ledger",
 "V11": "delivery_interpreted cites an earlier delivery_retained (lower seq) of the same delivery_id",
 "V12": "delivery_retained size and sha256 equal the carried response bytes; payload retained before any interpretation",
 "V13": "recovery segment contains only recovery_opened, evidence_gap_recorded, stop_recorded, plan_terminal stopped_hard_failure, final_audit and submission_quarantined",
 "V14": "plan_terminal.state equals terminal_derivation",
 "V15": "slot_closed.classification equals slot_closure_rule applied to retained events",
 "V16": "plan_terminal in the main segment has no open slot",
 "V17": "after plan_terminal only submission_quarantined, evidence_gap_recorded, delivery_retained of kind unsolicited or redelivery, final_audit and audit_revision are legal",
 "V18": "no reservation_made or dispatch_recorded after stop_recorded",
 "V19": "final_audit and audit_revision inventories equal inventories recomputed from the verified events they cite",
 "V20": "plan_terminal appears exactly once",
 "V21": "recovery_opened.last_verified_seq equals the computed last verified main seq",
 "V22": "an independently_verified claim whose verifier is absent from the external registry is counted as a rejected claim and downgraded to declared",
 "V23": "delivery_retained of kind dispatched only while that slot is open",
 "V24": "usage_reconciled at most once per distinct attempt_id",
 "V25": "delivery_interpreted.decision equals the decision_table result",
 "V26": "stop_recorded at most once",
 "V27": "stop_recorded.primary equals the highest-precedence cause listed",
 "V28": "usage_known false when usage is needed for a ceiling requires stop_recorded with hard_evidence_failure before the next reservation"
}

